using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace GSAIServicesAPI.Models
{
    /// <summary>
    /// EF Core entity that maps to the <c>teacher_documents</c> database table.
    /// Represents a document generated by an AI tool and saved by a teacher.
    /// Every row is owned by a single user — all queries must filter by <see cref="UserId"/>
    /// to ensure data isolation between users.
    /// </summary>
    [Table("teacher_documents")]
    public class TeacherDocument
    {
        /// <summary>
        /// Primary key of the document. Either a client-supplied value from <c>DocumentRequest.Id</c>
        /// or a server-generated <see cref="Guid"/> string when the client omits it.
        /// Maps to the <c>id</c> column.
        /// </summary>
        [Key]
        [Column("id")]
        public string Id { get; set; } = null!;

        /// <summary>
        /// The ID of the user who owns this document, resolved from the session token at creation time.
        /// Never sourced from the client payload — see <c>DocumentRequest.UserId</c> for the security rationale.
        /// Maps to the <c>user_id</c> column.
        /// </summary>
        [Column("user_id")]
        public string UserId { get; set; } = null!;

        /// <summary>
        /// The display title of the document shown to the user in listings and headings.
        /// Maps to the <c>title</c> column.
        /// </summary>
        [Column("title")]
        public string? Title { get; set; }

        /// <summary>
        /// The full generated content of the document, typically HTML or plain text,
        /// as returned by the AI model and displayed to the teacher.
        /// Maps to the <c>content</c> column.
        /// </summary>
        [Column("content")]
        public string? Content { get; set; }

        /// <summary>
        /// The human-readable name of the AI tool that generated this document (e.g. "Lesson Planner").
        /// Used for display and filtering purposes on the client.
        /// Maps to the <c>tool_title</c> column.
        /// </summary>
        [Column("tool_title")]
        public string? ToolTitle { get; set; }

        /// <summary>
        /// The category or subject area this document belongs to (e.g. "Mathematics", "Science").
        /// Used to group and filter documents in the UI.
        /// Maps to the <c>category</c> column.
        /// </summary>
        [Column("category")]
        public string? Category { get; set; }

        /// <summary>
        /// The document kind or output type produced by the AI tool (e.g. "Rubric", "Exam", "Summary").
        /// Allows the client to apply different rendering or export strategies per type.
        /// Maps to the <c>kind</c> column.
        /// </summary>
        [Column("kind")]
        public string? Kind { get; set; }

        /// <summary>
        /// The AI model identifier used to generate the document's content (e.g. "claude-sonnet-4-6").
        /// Stored for auditing and reproducibility — lets the team know which model version produced a given output.
        /// Maps to the <c>model</c> column.
        /// </summary>
        [Column("model")]
        public string? Model { get; set; }

        /// <summary>
        /// The prompt that was submitted to the AI model to produce this document.
        /// Stored alongside <see cref="Content"/> so the output can be audited, refined, or regenerated later.
        /// Maps to the <c>prompt</c> column.
        /// </summary>
        [Column("prompt")]
        public string? Prompt { get; set; }

        /// <summary>
        /// The UTC timestamp of when the document was first created.
        /// Set once by the controller at insertion time and never modified afterwards.
        /// Maps to the <c>created_at</c> column.
        /// </summary>
        [Column("created_at")]
        public DateTime CreatedAt { get; set; }

        /// <summary>
        /// The UTC timestamp of the most recent update to the document.
        /// Refreshed on every <b>PATCH</b> operation by the controller.
        /// Maps to the <c>updated_at</c> column.
        /// </summary>
        [Column("updated_at")]
        public DateTime UpdatedAt { get; set; }
    }
}